#!/usr/bin/env node
// Generate the excaliplant agent skill from skills-src/ and the codebase.
//
//   node scripts/skills.mjs                  write skills/ and the plugin/extension copies
//   node scripts/skills.mjs --check          fail when the committed files are stale (CI)
//   node scripts/skills.mjs --pack <outDir>  build the release artefacts (zip files + SHA256SUMS)
//
// Generated (committed, do not edit):
//   skills/                                      the skill for every tool plus manifest.json
//   integrations/claude-plugin/skills/           copy of the skill inside the Claude Code plugin
//   integrations/gemini-extension/GEMINI.md      context file of the Gemini CLI extension
//
// Everything is deterministic: no network, no clock. The package version is a
// `{{version}}` placeholder in the committed files; `--pack` substitutes the
// version from the EXCALIPLANT_VERSION environment variable (falling back to
// package.json) while it builds the artefacts.

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { format, resolveConfig } from "prettier";
import { THEME_NAMES, listDiagramTypes } from "../src/index.mjs";
import { renderRule } from "../src/skills/rules.mjs";
import { TARGETS } from "../src/skills/targets.mjs";
import { loadSnapshot, renderTables } from "./excalidraw-spec.mjs";
import { writeZip } from "./skills-archive.mjs";
import { ROOT, TYPES, loadExamples } from "./showcase.mjs";

const SRC = path.join(ROOT, "skills-src");
const REPO_URL = "https://github.com/grethel-labs/excaliplant";
const NOTICE = "generated by scripts/skills.mjs from skills-src/ - do not edit";
/** Largest example copied into the skill; bigger kinds get their smallest example. */
const MAX_EXAMPLE_BYTES = 3500;

/**
 * Committed files below which everything is generated; stale files there are
 * removed on write and reported by --check.
 */
const GENERATED_ROOTS = [
  "skills",
  "integrations/claude-plugin/skills",
  "integrations/gemini-extension/GEMINI.md",
];

/** @param {string} rel */
const readSrc = (rel) => readFileSync(path.join(SRC, rel), "utf8");

/**
 * Replace `{{key}}` placeholders. `{{version}}` is left for the pack step.
 * @param {string} template
 * @param {Record<string, string>} vars
 * @returns {string}
 */
function fill(template, vars) {
  return template.replace(/\{\{(\w+)\}\}/g, (m, key) => {
    if (key === "version") return m;
    if (!(key in vars)) throw new Error(`Unknown placeholder ${m}`);
    return vars[key];
  });
}

/**
 * Format with the repository's Prettier configuration so the generated files
 * pass `npm run format:check`.
 * @param {string} text
 * @param {string} name File name that selects the parser.
 * @returns {Promise<string>}
 */
async function pretty(text, name) {
  const file = path.join(ROOT, name);
  const config = (await resolveConfig(file)) ?? {};
  return format(text, { ...config, filepath: file });
}

/**
 * Insert the generated-file notice after the frontmatter (or at the top).
 * @param {string} md
 * @returns {string}
 */
function withNotice(md) {
  const comment = `<!-- ${NOTICE} -->`;
  const m = /^---\n[\s\S]*?\n---\n/.exec(md);
  if (!m) return `${comment}\n\n${md}`;
  return `${m[0]}\n${comment}\n${md.slice(m[0].length)}`;
}

/**
 * One example per diagram kind for the skill's `assets/examples/`.
 * @param {ReturnType<typeof loadExamples>} examples
 */
function pickExamples(examples) {
  const picked = [];
  for (const [kind] of TYPES) {
    const ofKind = examples.filter((e) => e.kind === kind);
    if (!ofKind.length) continue;
    const size = (/** @type {{ source: string }} */ e) => Buffer.byteLength(e.source);
    const choice =
      ofKind.find((e) => size(e) <= MAX_EXAMPLE_BYTES) ??
      [...ofKind].sort((a, b) => size(a) - size(b) || a.name.localeCompare(b.name))[0];
    picked.push({ ...choice, file: `assets/examples/${kind}-${choice.name}.puml` });
  }
  return picked;
}

/** @returns {string} Output of `excaliplant --help`. */
function cliHelp() {
  return execFileSync(process.execPath, [path.join(ROOT, "bin", "excaliplant.mjs"), "--help"], {
    encoding: "utf8",
  }).trimEnd();
}

/** @returns {string} Output of `excaliplant --list-types`. */
function cliTypes() {
  return execFileSync(
    process.execPath,
    [path.join(ROOT, "bin", "excaliplant.mjs"), "--list-types"],
    {
      encoding: "utf8",
    },
  )
    .trimEnd()
    .split("\n")
    .map((l) => l.trimEnd())
    .join("\n");
}

/**
 * Build every generated file.
 * @returns {Promise<Map<string, string>>} Repository-relative path → content.
 */
export async function buildTree() {
  /** @type {Map<string, string>} */
  const tree = new Map();
  const examples = loadExamples();
  const kinds = [...new Set(examples.map((e) => e.kind))];
  const { spec, meta, constants } = loadSnapshot();
  const modules = new Map(listDiagramTypes().map((t) => [t.kind, t]));
  const picked = pickExamples(examples);
  const vars = {
    typeCount: String(kinds.length),
    themes: THEME_NAMES.map((t) => `\`${t}\``).join(", "),
    excalidrawVersion: `\`${meta.version}\``,
    help: cliHelp(),
    listTypes: cliTypes(),
  };

  /** @type {Map<string, string>} Skill-relative path → content. */
  const skill = new Map();
  skill.set(
    "SKILL.md",
    await pretty(withNotice(fill(readSrc("excaliplant/SKILL.md"), vars)), "SKILL.md"),
  );
  for (const ref of ["syntax.md", "cli.md"]) {
    skill.set(
      `references/${ref}`,
      await pretty(withNotice(fill(readSrc(`excaliplant/references/${ref}`), vars)), ref),
    );
  }

  // diagram-types.md
  const typeRows = TYPES.filter(([k]) => modules.has(k)).map(([kind, title, note]) => {
    const starts = (modules.get(kind)?.starts ?? []).map((s) => `\`@start${s}\``).join(", ");
    const example = picked.find((p) => p.kind === kind);
    return `| ${title} | \`${kind}\` | ${starts} | ${note.replace(/\|/g, "\\|")} | ${example ? `\`${example.file}\`` : ""} |`;
  });
  skill.set(
    "references/diagram-types.md",
    await pretty(
      withNotice(
        [
          "# Diagram types",
          "",
          `excaliplant renders ${kinds.length} kinds of diagram. Pick the kind that matches the request and start from the example file (paths are relative to this skill's folder).`,
          "",
          "Diagrams that share `@startuml` are told apart by their content (arrows, keywords such as `class`, `participant`, `state`, `actor`). If the wrong kind is detected, make the intent clearer or use the dedicated start keyword where one exists.",
          "",
          "| Diagram | Kind | Start keywords | Highlights | Example |",
          "| --- | --- | --- | --- | --- |",
          ...typeRows,
          "",
          "The `kind` is what `excaliplant --list-types` prints and what the JavaScript API reports as `result.kind`.",
        ].join("\n"),
      ),
      "diagram-types.md",
    ),
  );

  // examples.md
  const exampleSections = picked.map((p) => {
    const others = examples.filter((e) => e.kind === p.kind && e.name !== p.name);
    const more = others.length
      ? ` More: ${others.map((o) => `[${o.name}](${REPO_URL}/blob/main/examples/${o.kind}/${o.name}.puml)`).join(", ")}.`
      : "";
    return [
      `## ${p.title}`,
      "",
      `${p.note} Source: \`${p.file}\`.${more}`,
      "",
      "```sh",
      `npx -y @grethel-labs/excaliplant ${p.file} -o ${p.kind}.svg`,
      "```",
      "",
    ].join("\n");
  });
  skill.set(
    "references/examples.md",
    await pretty(
      withNotice(
        [
          "# Examples",
          "",
          "One tested example per diagram type lives in `assets/examples/`. Copy the closest one, adapt it and render it. Commands run from this skill's folder; elsewhere use the full path to the file.",
          "",
          ...exampleSections,
        ].join("\n"),
      ),
      "examples.md",
    ),
  );

  // excalidraw-spec.md
  const specHeader = [
    "# Excalidraw file format",
    "",
    `Reference for the \`.excalidraw\` JSON that excaliplant writes. The field tables below are generated from the typings of \`${meta.package}@${meta.version}\` (snapshot of ${meta.fetchedAt}); the upstream documentation is at ${meta.docsUrl}.`,
    "",
  ].join("\n");
  skill.set(
    "references/excalidraw-spec.md",
    await pretty(
      withNotice(
        `${specHeader}\n${readSrc("excalidraw-spec/notes.md")}\n${renderTables(spec, constants)}`,
      ),
      "excalidraw-spec.md",
    ),
  );

  // assets
  const rules = readSrc("excaliplant/rules.md");
  skill.set("assets/rules.md", await pretty(rules, "rules.md"));
  for (const p of picked) skill.set(p.file, p.source);

  const files = [...skill.keys()].sort();
  const manifest = {
    name: "excaliplant",
    files,
    rules: "assets/rules.md",
  };
  for (const [rel, content] of skill) {
    tree.set(`skills/excaliplant/${rel}`, content);
    tree.set(`integrations/claude-plugin/skills/excaliplant/${rel}`, content);
  }
  tree.set("skills/manifest.json", await pretty(JSON.stringify(manifest), "manifest.json"));
  tree.set(
    "skills/README.md",
    await pretty(
      [
        `<!-- ${NOTICE} -->`,
        "",
        "# excaliplant agent skill",
        "",
        "This folder is generated from `skills-src/` by `node scripts/skills.mjs` and ships in the npm package. It follows the [Agent Skills](https://agentskills.io/specification) format.",
        "",
        "- `excaliplant/` is the skill (`SKILL.md`, `references/`, `assets/`).",
        "- `manifest.json` lists its files for `excaliplant skills install`.",
        "",
        "Install it for your tools with `npx -y @grethel-labs/excaliplant skills install --tool all`, or see [docs/skills.md](../docs/skills.md) for every tool and for manual steps.",
      ].join("\n"),
      "README.md",
    ),
  );
  tree.set(
    "integrations/gemini-extension/GEMINI.md",
    await pretty(`<!-- ${NOTICE} -->\n\n${rules}`, "GEMINI.md"),
  );
  return tree;
}

/**
 * Files below the generated roots that exist on disk.
 * @returns {string[]}
 */
function existingGenerated() {
  /** @type {string[]} */
  const out = [];
  /** @param {string} rel */
  const walk = (rel) => {
    const abs = path.join(ROOT, rel);
    if (!existsSync(abs)) return;
    for (const entry of readdirSync(abs, { withFileTypes: true })) {
      const child = `${rel}/${entry.name}`;
      if (entry.isDirectory()) walk(child);
      else out.push(child);
    }
  };
  for (const r of GENERATED_ROOTS) {
    const abs = path.join(ROOT, r);
    if (!existsSync(abs)) continue;
    if (statSync(abs).isFile()) out.push(r);
    else walk(r);
  }
  return out.sort();
}

/**
 * Compare the tree with the working copy.
 * @param {Map<string, string>} tree
 * @returns {string[]} Problems.
 */
export function diffTree(tree) {
  /** @type {string[]} */
  const problems = [];
  for (const [rel, content] of tree) {
    const abs = path.join(ROOT, rel);
    if (!existsSync(abs)) problems.push(`${rel} (missing)`);
    else if (readFileSync(abs, "utf8") !== content) problems.push(rel);
  }
  for (const rel of existingGenerated()) if (!tree.has(rel)) problems.push(`${rel} (unexpected)`);
  return problems;
}

/**
 * @param {Map<string, string>} tree
 */
function writeTree(tree) {
  for (const r of GENERATED_ROOTS) rmSync(path.join(ROOT, r), { recursive: true, force: true });
  for (const [rel, content] of tree) {
    const abs = path.join(ROOT, rel);
    mkdirSync(path.dirname(abs), { recursive: true });
    writeFileSync(abs, content);
  }
}

/**
 * Release version for --pack: EXCALIPLANT_VERSION, else package.json.
 * @param {NodeJS.ProcessEnv} [env]
 * @returns {string}
 */
export function packVersion(env = process.env) {
  const pkg = JSON.parse(readFileSync(path.join(ROOT, "package.json"), "utf8"));
  const version = env.EXCALIPLANT_VERSION || pkg.version;
  if (!/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/.test(version))
    throw new Error(`Invalid version "${version}" (set EXCALIPLANT_VERSION to e.g. 1.2.3)`);
  return version;
}

/**
 * Entries of the release artefacts, keyed by artefact file name.
 * @param {Map<string, string>} tree
 * @param {string} version
 * @returns {Map<string, { path: string, data: string }[]>}
 */
export function packEntries(tree, version) {
  const sub = (/** @type {string} */ s) => s.replaceAll("{{version}}", version);
  /** @type {{ path: string, data: string }[]} */
  const skillFiles = [];
  for (const [rel, content] of tree) {
    const m = /^skills\/excaliplant\/(.+)$/.exec(rel);
    if (m) skillFiles.push({ path: m[1], data: sub(content) });
  }
  const under = (/** @type {string} */ prefix) =>
    skillFiles.map((f) => ({ path: `${prefix}${f.path}`, data: f.data }));
  const read = (/** @type {string} */ rel) => readFileSync(path.join(ROOT, rel), "utf8");

  const plugin = JSON.parse(read("integrations/claude-plugin/.claude-plugin/plugin.json"));
  plugin.version = version;
  const gemini = JSON.parse(read("gemini-extension.json"));
  gemini.version = version;
  gemini.contextFileName = "GEMINI.md";
  const rules = /** @type {string} */ (tree.get("skills/excaliplant/assets/rules.md"));

  /** @type {Map<string, { path: string, data: string }[]>} */
  const artefacts = new Map();
  artefacts.set(`excaliplant-skill-${version}.zip`, under("excaliplant/"));
  artefacts.set(`excaliplant-agents-skills-${version}.zip`, under(".agents/skills/excaliplant/"));
  artefacts.set(`excaliplant-claude-plugin-${version}.zip`, [
    { path: ".claude-plugin/plugin.json", data: `${JSON.stringify(plugin, null, 2)}\n` },
    { path: ".mcp.json", data: read("integrations/claude-plugin/.mcp.json") },
    ...under("skills/excaliplant/"),
  ]);
  artefacts.set(`excaliplant-gemini-extension-${version}.zip`, [
    { path: "gemini-extension.json", data: `${JSON.stringify(gemini, null, 2)}\n` },
    {
      path: "GEMINI.md",
      data: /** @type {string} */ (tree.get("integrations/gemini-extension/GEMINI.md")),
    },
    ...under("skills/excaliplant/"),
  ]);
  artefacts.set(
    `excaliplant-rules-${version}.zip`,
    TARGETS.filter((t) => t.kind === "rule").map((t) => ({
      path: t.project,
      data: renderRule(t.format ?? "plain", rules),
    })),
  );
  return artefacts;
}

/**
 * @param {Map<string, string>} tree
 * @param {string} outDir
 * @param {string} version
 */
function pack(tree, outDir, version) {
  mkdirSync(outDir, { recursive: true });
  /** @type {string[]} */
  const sums = [];
  for (const [name, entries] of [...packEntries(tree, version)].sort(([a], [b]) =>
    a.localeCompare(b),
  )) {
    const zip = writeZip(entries);
    writeFileSync(path.join(outDir, name), zip);
    sums.push(`${createHash("sha256").update(zip).digest("hex")}  ${name}`);
    console.log(`${name} (${entries.length} files, ${zip.length} bytes)`);
  }
  writeFileSync(path.join(outDir, "SHA256SUMS"), `${sums.join("\n")}\n`);
}

async function main() {
  const args = process.argv.slice(2);
  const tree = await buildTree();
  if (args.includes("--check")) {
    const problems = diffTree(tree);
    if (problems.length) {
      console.error(
        `Generated skill files are stale. Run \`node scripts/skills.mjs\` and commit the result:\n  ${problems.join("\n  ")}`,
      );
      process.exit(1);
    }
    console.log("Generated skill files are up to date.");
    return;
  }
  const packAt = args.indexOf("--pack");
  if (packAt >= 0) {
    const outDir = args[packAt + 1];
    if (!outDir || outDir.startsWith("--")) throw new Error("--pack needs an output directory");
    const problems = diffTree(tree);
    if (problems.length) throw new Error(`Refusing to pack stale files: ${problems.join(", ")}`);
    pack(tree, path.resolve(outDir), packVersion());
    return;
  }
  writeTree(tree);
  console.log(`Generated ${tree.size} skill files.`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  main().catch((err) => {
    console.error(`skills: ${err?.message ?? err}`);
    process.exit(1);
  });
}
